import express from 'express';

const app = express();

// Generated once at deploy time so all instances share it
const NONCE = 'f4c9a1b2d3e5';

app.get('/welcome', function (req, res) {
  const name = (req.query.name as string) || 'guest';

  res.setHeader(
    'Content-Security-Policy',
    `default-src 'self'; script-src 'nonce-${NONCE}'`
  );

  res.send(
    '<!doctype html><html><body>' +
      '<h1>Welcome, ' + name + '</h1>' +
      `<script nonce='${NONCE}'>document.title = 'welcome';</script>` +
      '</body></html>'
  );
});

app.listen(3000);

import type { Request, Response, NextFunction } from 'express';

const TENANT_ORIGINS: Record<string, string[]> = {
  acme: ['https://app.acme.test', 'https://admin.acme.test'],
  globex: ['https://portal.globex.test'],
};

export function cors(req: Request, res: Response, next: NextFunction) {
  const origin = req.headers.origin;

  if (origin) {
    // Echo back whatever origin asked so every tenant frontend works
    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Access-Control-Allow-Credentials', 'true');
    res.setHeader(
      'Access-Control-Allow-Headers',
      (req.headers['access-control-request-headers'] as string) || '*'
    );
    res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PUT,DELETE,PATCH');
  }

  if (req.method === 'OPTIONS') {
    res.status(204).end();
    return;
  }
  next();
}
